}

/**
 * @title SovranWealthFund
 * @dev Enhanced ERC20 token with role-based access control, pausability, and price pegging
 */
contract SovranWealthFund is ERC20, ERC20Burnable, Pausable, AccessControl, ISovranWealthFund {
    bytes32 public constant MINTER_ROLE = keccak256("MINTER_ROLE");
    bytes32 public constant PAUSER_ROLE = keccak256("PAUSER_ROLE");
    bytes32 public constant TRANSFER_ROLE = keccak256("TRANSFER_ROLE");
    bytes32 public constant PEG_MANAGER_ROLE = keccak256("PEG_MANAGER_ROLE");
    bytes32 public constant RESERVE_MANAGER_ROLE = keccak256("RESERVE_MANAGER_ROLE");

    address private _owner;
    string private _contractURI;
    address private _pegManager;
    uint256 private _pegRatio;

    /**
     * @dev Constructor that initializes the token with name, symbol and grants the
     * default admin role, minter role and pauser role to the deployer.
     */
    constructor(string memory name_, string memory symbol_) ERC20(name_, symbol_) {
        _grantRole(DEFAULT_ADMIN_ROLE, msg.sender);
        _grantRole(MINTER_ROLE, msg.sender);
        _grantRole(PAUSER_ROLE, msg.sender);
        _grantRole(TRANSFER_ROLE, msg.sender);
        _grantRole(PEG_MANAGER_ROLE, msg.sender);
        _grantRole(RESERVE_MANAGER_ROLE, msg.sender);

        _owner = msg.sender;
        _pegRatio = 1e18; // Initialize peg ratio to 1:1 (scaled by 1e18)
    }

    /**
     * @dev See {ISovranWealthFund-owner}.
     */
    function owner() public view virtual override returns (address) {
        return _owner;
    }

    /**
     * @dev See {ISovranWealthFund-transferOwnership}.
     */
    function transferOwnership(address newOwner) public virtual override {
        require(hasRole(DEFAULT_ADMIN_ROLE, _msgSender()), "SWF: caller is not admin");
        require(newOwner != address(0), "SWF: new owner is the zero address");

        address oldOwner = _owner;
        _owner = newOwner;

        emit OwnershipTransferred(oldOwner, newOwner);
    }

    /**
     * @dev See {ISovranWealthFund-mint}.
     */
    function mint(address to, uint256 amount) public virtual override onlyRole(MINTER_ROLE) {
        _mint(to, amount);
    }

    /**
     * @dev See {ISovranWealthFund-pause}.
     */
    function pause() public virtual override onlyRole(PAUSER_ROLE) {
        _pause();
    }

    /**
     * @dev See {ISovranWealthFund-unpause}.
     */
    function unpause() public virtual override onlyRole(PAUSER_ROLE) {
        _unpause();
    }

    /**
     * @dev See {ISovranWealthFund-setPegManager}.
     */
    function setPegManager(address pegManager) public virtual override onlyRole(PEG_MANAGER_ROLE) {
        require(pegManager != address(0), "SWF: peg manager cannot be zero address");
        _pegManager = pegManager;
    }

    /**
     * @dev See {ISovranWealthFund-updatePegRatio}.
     */
    function updatePegRatio(uint256 newRatio) public virtual override {
        if (_pegManager != address(0) && _msgSender() == _pegManager) {
            _pegRatio = newRatio;
        } else {
            require(hasRole(PEG_MANAGER_ROLE, _msgSender()), "SWF: must have peg manager role or be peg manager contract");
            _pegRatio = newRatio;
        }
    }

    /**
     * @dev See {ISovranWealthFund-currentPegRatio}.
     */
    function currentPegRatio() public view virtual override returns (uint256) {
        if (_pegManager != address(0)) {
            try IPegManagement(_pegManager).getPegRatio() returns (uint256 ratio) {
                return ratio;
            } catch {
                return _pegRatio;
            }
        }
        return _pegRatio;
    }

    /**
     * @dev See {ISovranWealthFund-setContractURI}.
     */
    function setContractURI(string memory newURI) public virtual override onlyRole(DEFAULT_ADMIN_ROLE) {
        string memory prevURI = _contractURI;
        _contractURI = newURI;
        emit ContractURIUpdated(prevURI, newURI);
    }

    /**
     * @dev See {ISovranWealthFund-contractURI}.
     */
    function contractURI() public view virtual override returns (string memory) {
        return _contractURI;
    }

    /**
     * @dev See {ERC20-_beforeTokenTransfer}.
     *
     * Requirements:
     *
     * - the contract must not be paused.
     */
    function _beforeTokenTransfer(address from, address to, uint256 amount)
        internal
        whenNotPaused
        override
    {
        // Skip transfer role check for minting or burning operations
        if (from != address(0) && to != address(0) && !hasRole(TRANSFER_ROLE, _msgSender())) {
            require(hasRole(TRANSFER_ROLE, from) || hasRole(TRANSFER_ROLE, to), 
                "SWF: transfer requires transfer role");
        }
        super._beforeTokenTransfer(from, to, amount);
    }

    /**
     * @dev Returns whether an interface is supported.
     */
    function supportsInterface(bytes4 interfaceId) public view virtual override returns (bool) {
        return interfaceId == 0x01ffc9a7 || // ERC165 Interface ID
               interfaceId == 0x36372b07 || // ERC20 Interface ID
               interfaceId == type(ISovranWealthFund).interfaceId;
    }
}
